1039	/// Does the lexical scope chain from `from` UP TO **but excluding** the enclosing
1040	/// module/root contain any potential block-local shadow of `leading` at `byte`?
1041	/// Three shapes (§8.1 decision ①C / re-review BLOCKER): (a) an exact `NS_TYPE`
1042	/// binding, (b) a block-local glob `Edge` whose `glob_vis_range` covers `byte`,
1043	/// (c) a covering `NS_TYPE` macro wildcard. ANY ⇒ shadow (keep-all).
1044	///
1045	/// **Why the scan excludes the module/root scope (plan re-confirm BLOCKER-1).**
1046	/// A bare `T::m` anchors its leading ident at the **enclosing module** (`RustPolicy`
1047	/// `anchor` for `AnchorKind::Bare`, rust_policy.rs:296-302), and the resolved type
1048	/// `T`'s OWN definition is a module/root `NS_TYPE` `Resolved(Item)` binding
1049	/// (`walk_struct`, walk/types.rs:52). If the scan INCLUDED the module/root scope,
1050	/// shape (a) would match that very def-binding and classify `T`'s own definition as
1051	/// a "shadow" — keep-all would fire on EVERY direct in-module type, so the headline
1052	/// `CliTest::with_file` singleton recovery could never run. ①C only guards
1053	/// **block-local** shadows the module-anchored ②B resolution cannot see; those live
1054	/// strictly below the module (a block-local `use`/`struct`/macro lands in a
1055	/// `Block`/`Callable`/`Type` scope: locals.rs Block/Callable scopes, items.rs
1056	/// item-position bindings). A *module-level* `use Foo` is ②B's domain — it is a
1057	/// `Pending` module-rib binding, so ②B already keeps-all. So excluding the
1058	/// module/root loses no real shadow (recall-safe) and only removes the
1059	/// self-shadow false positive. (Shape (b) is independently safe: a module/root glob
1060	/// records `glob_vis_range == None` — items.rs:205 — so it could never match the
1061	/// `is_some_and` byte-cover check regardless.)
1062	fn leading_segment_has_block_local_shadow(
1063	    graph: &ScopeGraph,
1064	    from: ScopeId,
1065	    file: FileId,
1066	    byte: usize,
1067	    leading: &str,
1068	) -> bool {
1069	    let at = SourceLoc { file, byte };
1070	    for scope in scope_chain_below_module(graph, from) {
1071	        // (a) an exact-ident NS_TYPE binding in this block/callable/type scope
1072	        //     whose visibility extent covers the call byte.
1073	        let exact_binding = graph.bindings.iter().any(|b| {
1074	            b.scope == scope
1075	                && b.name == leading
1076	                && b.ns == NS_TYPE
1077	                && binding_vis_covers(b, &at)
1078	        });
1079	        if exact_binding {
1080	            return true;
1081	        }
1082	        // (b) a block-local glob edge whose glob_vis_range covers the call byte.
1083	        let glob_shadow = graph.edges.iter().any(|e| {
1084	            e.from == scope
1085	                && e.kind == EK_GLOB
1086	                && e.vis_range.as_ref().is_some_and(|s| span_covers(s, &at))
1087	        });
1088	        if glob_shadow {
1089	            return true;
1090	        }
1091	        // (c) a covering NS_TYPE macro wildcard in this scope.
1092	        let macro_shadow = graph
1093	            .macro_wildcards
1094	            .iter()
1095	            .any(|m| m.scope == scope && m.ns == NS_TYPE && span_covers(&m.range, &at));
1096	        if macro_shadow {
1097	            return true;
1098	        }
1099	    }
1100	    false
1101	}
