1103	/// The lexical scope chain from `from` up to but **EXCLUDING** the enclosing
1104	/// `Module`/`Root` — the block/callable/type region strictly between the call site
1105	/// and its enclosing module, where a bare `T::m` anchor's leading ident could be
1106	/// block-locally shadowed (member lookup has no lexical fall-out, so a shadow here
1107	/// is invisible to the module-anchored path — §8.1). The module/root scope itself
1108	/// is **NOT** scanned: the resolved type `T`'s own def-binding lives there, and
1109	/// including it would self-shadow every direct in-module type and defeat the
1110	/// recovery (plan re-confirm BLOCKER-1); module-level imports are ②B's domain.
1111	fn scope_chain_below_module(graph: &ScopeGraph, from: ScopeId) -> Vec<ScopeId> {
1112	    use crate::name_resolution::types::ScopeKind;
1113	    let mut out = Vec::new();
1114	    let mut cur = Some(from);
1115	    while let Some(id) = cur {
1116	        let Some(s) = graph.scope(id) else { break };
1117	        if matches!(s.kind, ScopeKind::Module | ScopeKind::Root) {
1118	            break; // stop AT the module/root WITHOUT scanning it
1119	        }
1120	        out.push(id);
1121	        cur = s.parent;
1122	    }
1123	    out
1124	}
