1126	/// `Binding::vis_extents` cover `at` (empty extents ⇒ scope-wide ⇒ covered),
1127	/// mirroring the engine's `vis_extent_covers`.
1128	fn binding_vis_covers(b: &Binding, at: &SourceLoc) -> bool {
1129	    if b.vis_extents.is_empty() {
1130	        return true;
1131	    }
1132	    b.vis_extents.iter().any(|s| span_covers(s, at))
1133	}
1134	
1135	/// Half-open `[lo, hi)` same-file span cover (mirrors `engine::span_covers`).
1136	fn span_covers(s: &Span, at: &SourceLoc) -> bool {
1137	    s.lo.file == at.file && at.byte >= s.lo.byte && at.byte < s.hi.byte
1138	}
