1785	Then add the prune helper (place it next to `rust_scope_graph_resolution`):
1786	
1787	```rust
1788	    /// Owner-keyed disproof prune (spec §4). Fetch the bare `(owner, method)` pool
1789	    /// from `self.methods`, run the `ScopeResolution` predicate, and decide:
1790	    /// 1 survivor → Exact (recovery); >1 → demoted (pruned NameOnly); unchanged
1791	    /// from the bare pool → `None` (fall through to the #120 demote floor). Only
1792	    /// reduces below the bare pool when the predicate actually disproved someone.
1793	    fn rust_scope_prune_owner(
1794	        &self,
1795	        graph: &ScopeGraph,
1796	        site: &CallSite,
1797	        file: FileId,
1798	        from: ScopeId,
1799	        name: &str,
1800	    ) -> Option<Vec<ResolvedCallee<'_>>> {
1801	        // Owner key `(T, m)` from `mod::T::m` (shared with the splice via
1802	        // owner_method_key, so both agree on the bare key).
1803	        let (owner, method) = owner_method_key(name)?;
1804	        let pool_ids = self.methods.get(&(owner, method))?;
1805	        let pool: Vec<&FunctionId> = pool_ids.iter().collect();
1806	        let pred = ScopeResolution::new(self);
1807	        let cx = crate::resolution_disproof::DisproofCx { graph, file, from };
1808	        let pruned = crate::resolution_disproof::prune(
1809	            pool.clone(),
1810	            site,
1811	            &cx,
1812	            &[&pred as &dyn crate::resolution_disproof::DisproofPredicate],
1813	        );
1814	        // Unchanged from the bare pool → the predicate proved nothing → fall
1815	        // through to the #120 demote floor (do NOT mint here).
1816	        if pruned.len() == pool.len() {
1817	            return None;
1818	        }
1819	        Some(match pruned.len() {
1820	            1 => exact(pruned, ResolutionKind::QualifiedOwner),
1821	            _ => demoted(pruned, ResolutionKind::QualifiedOwner),
1822	        })
1823	    }
1824	```
