1208	/// The one shipped disproof predicate (spec §3). Disproves a candidate only when
1209	/// the owner type-path's leading segment binds directly to an in-repo item (②B),
1210	/// has no block-local shadow at the call site (①C), and the graph is
1211	/// edition-uniform (§2 guard). On all uncertainty it disproves nothing.
1212	pub struct ScopeResolution<'a> {
1213	    cg: &'a CallGraph,
1214	}
1215	
1216	impl<'a> ScopeResolution<'a> {
1217	    pub fn new(cg: &'a CallGraph) -> Self {
1218	        ScopeResolution { cg }
1219	    }
1220	}
