1222	impl crate::resolution_disproof::DisproofPredicate for ScopeResolution<'_> {
1223	    fn disproves(
1224	        &self,
1225	        cand: &FunctionId,
1226	        site: &CallSite,
1227	        cx: &crate::resolution_disproof::DisproofCx<'_>,
1228	    ) -> bool {
1229	        let graph = cx.graph;
1230	        // §2 guard: a non-uniform-edition workspace is non-authoritative for
1231	        // disproof. Keep-all.
1232	        if !graph.edition_uniform {
1233	            return false;
1234	        }
1235	
1236	        // Only `T::m` / `mod::T::m` owner paths are in scope for this predicate.
1237	        let Some((anchor, path)) = rust_call_path_anchor(site.callee_name.as_str()) else {
1238	            return false;
1239	        };
1240	        // The leading type segment is the path's first segment; the trailing
1241	        // segment is the method. A path with <2 segments has no owner type.
1242	        if path.0.len() < 2 {
1243	            return false;
1244	        }
1245	        let leading = &path.0[0];
1246	
1247	        // ①C: any potential block-local shadow of the leading ident -> keep-all.
1248	        if leading_segment_has_block_local_shadow(graph, cx.from, cx.file, site.start_byte, leading)
1249	        {
1250	            return false;
1251	        }
1252	
1253	        // ②B: the leading segment must bind directly to an in-repo Item, with no
1254	        // Pending hop. Prove this from the binding shape, not Candidate provenance.
1255	        if !leading_segment_binds_directly(
1256	            graph,
1257	            cx.file,
1258	            cx.from,
1259	            site.start_byte,
1260	            &anchor,
1261	            leading,
1262	        ) {
1263	            return false;
1264	        }
1265	
1266	        // Both contracts hold. Resolve the final callable target and disprove
1267	        // `cand` iff it is not in that target's in-repo id set.
1268	        let Some(target) = rust_graph_qualified_callable_edge(graph, site, cx.file, cx.from) else {
1269	            return false;
1270	        };
1271	        let ids = self.cg.graph_target_ids(graph, &target);
1272	        if ids.is_empty() {
1273	            return false;
1274	        }
1275	        !ids.contains(&cand)
1276	    }
1277	}
1278	
1279	/// Prove the leading type segment binds directly at the call site: the binding
1280	/// the call site sees for `leading` is itself a non-glob, non-Pending
1281	/// `BindTarget::Resolved(Target::Item)` (§8.2 decision ②B).
1282	fn leading_segment_binds_directly(
1283	    graph: &ScopeGraph,
1284	    file: FileId,
1285	    from: ScopeId,
1286	    byte: usize,
1287	    anchor: &Anchor,
1288	    leading: &str,
1289	) -> bool {
1290	    let at = SourceLoc { file, byte };
1291	    let policy = RustPolicy::new(graph, graph.edition);
1292	    let Some((start, _)) = policy.anchor(anchor, from) else {
1293	        return false;
1294	    };
1295	
1296	    let rib: Vec<&Binding> = graph
1297	        .bindings
1298	        .iter()
1299	        .filter(|b| b.scope == start && b.name == leading && b.ns == NS_TYPE)
1300	        .collect();
1301	    if rib.is_empty() {
1302	        return false;
1303	    }
1304	
1305	    let q = ResolveQuery {
1306	        name: leading.to_string(),
1307	        ns: NS_TYPE,
1308	        from,
1309	        at: at.clone(),
1310	        cfg: Default::default(),
1311	        ctx: Default::default(),
1312	    };
1313	    let visible: Vec<&Binding> = rib
1314	        .into_iter()
1315	        .filter(|b| {
1316	            let trav = TraversalCtx {
1317	                lookup_scope: Some(b.scope),
1318	                via_glob: false,
1319	                edge_kind: None,
1320	            };
1321	            policy.visible(b, &q, &trav)
1322	        })
1323	        .collect();
1324	
1325	    match visible.as_slice() {
1326	        [b] => matches!(&b.target, BindTarget::Resolved(Target::Item { .. })),
1327	        _ => false,
1328	    }
1329	}
1330	
1331	/// Does the lexical scope chain from `from` up to but excluding the enclosing
1332	/// module/root contain any potential block-local shadow of `leading` at `byte`?
1333	/// Three shapes (§8.1 decision ①C): exact `NS_TYPE` binding, block-local glob
1334	/// edge covering the call byte, or covering `NS_TYPE` macro wildcard.
1335	fn leading_segment_has_block_local_shadow(
1336	    graph: &ScopeGraph,
1337	    from: ScopeId,
1338	    file: FileId,
1339	    byte: usize,
1340	    leading: &str,
1341	) -> bool {
1342	    let at = SourceLoc { file, byte };
1343	    for scope in scope_chain_below_module(graph, from) {
1344	        let exact_binding = graph.bindings.iter().any(|b| {
1345	            b.scope == scope && b.name == leading && b.ns == NS_TYPE && binding_vis_covers(b, &at)
1346	        });
1347	        if exact_binding {
1348	            return true;
1349	        }
1350	
1351	        let glob_shadow = graph.edges.iter().any(|e: &Edge| {
1352	            e.from == scope
1353	                && e.kind == EK_GLOB
1354	                && e.vis_range.as_ref().is_some_and(|s| span_covers(s, &at))
1355	        });
1356	        if glob_shadow {
1357	            return true;
1358	        }
1359	
1360	        let macro_shadow = graph
1361	            .macro_wildcards
1362	            .iter()
1363	            .any(|m| m.scope == scope && m.ns == NS_TYPE && span_covers(&m.range, &at));
1364	        if macro_shadow {
1365	            return true;
1366	        }
1367	    }
1368	    false
1369	}
1370	
1371	/// The lexical scope chain from `from` up to but excluding the enclosing
1372	/// `Module`/`Root`. The module/root scope itself is not scanned: the resolved
1373	/// type's own def-binding lives there and would self-shadow every direct type.
1374	fn scope_chain_below_module(graph: &ScopeGraph, from: ScopeId) -> Vec<ScopeId> {
1375	    use crate::name_resolution::types::ScopeKind;
1376	
1377	    let mut out = Vec::new();
1378	    let mut cur = Some(from);
1379	    while let Some(id) = cur {
1380	        let Some(s) = graph.scope(id) else { break };
1381	        if matches!(s.kind, ScopeKind::Module | ScopeKind::Root) {
1382	            break;
1383	        }
1384	        out.push(id);
